begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.attention_policies(school_id,version,minimum_decline,max_score,missing_due_count,window_days,approved_by)select'10000000-0000-4000-8000-000000000001',coalesce(max(version),0)+1,3,10,2,14,'20000000-0000-4000-8000-000000000001'from app.attention_policies where school_id='10000000-0000-4000-8000-000000000001';
create temporary table attention_ids(baseline uuid,followup uuid);grant select,insert,update on attention_ids to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','97000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Attention source fixture','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,due_at)select'10000000-0000-4000-8000-000000000001',('97010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'97000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Factual task '||i,'School authored',10,'61000000-0000-4000-8000-000000000001',case when i>2 then clock_timestamp()-interval'1 day'else null end from generate_series(1,5)i;
insert into app.submissions(school_id,id,assessment_id,learner_id,content)select'10000000-0000-4000-8000-000000000001',('97020000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('97010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000024','Immutable factual example'from generate_series(1,2)i;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into attention_ids(baseline,followup)select internal.release_marking(internal.mark_submission('97020000-0000-4000-8000-000000000001',8,'Reviewed baseline',1,0,true),1,true),internal.release_marking(internal.mark_submission('97020000-0000-4000-8000-000000000002',3,'Reviewed follow-up',1,0,true),1,true);
reset role;
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,completed_at)select'10000000-0000-4000-8000-000000000001',gen_random_uuid(),'20000000-0000-4000-8000-000000000004','result.released','result',result_id,1,'{}','attention-fixture:'||result_id::text,'COMPLETED',clock_timestamp()from(select baseline result_id from attention_ids union all select followup from attention_ids)source;
insert into internal.processed_events(event_id,school_id,source_type,source_id)select id,school_id,'RESULT',entity_id from internal.outbox_events where deduplication_key like'attention-fixture:%';
select lives_ok($$select internal.refresh_native_attention('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000024')$$,'compatible processed 8 to 3 produces factual decline');
select lives_ok($$select internal.refresh_native_attention('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000030')$$,'due missing submissions produce evidence-absence context');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000024',true);
select ok(exists(select 1 from jsonb_array_elements(internal.read_attention_signals(100,null,'20000000-0000-4000-8000-000000000024')->'items')item where item->>'type'='native_result_decline'and item->>'difference'='-5'and item->'baseline'->>'score'='8'and item->'followUp'->>'score'='3'),'decline retains actual native values and difference');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000030',true);
select ok(exists(select 1 from jsonb_array_elements(internal.read_attention_signals(100,null,'20000000-0000-4000-8000-000000000030')->'items')item where item->>'type'='missing_due_work'and(item->>'count')::integer>=3 and item->>'uncertainty'='MISSING_SUBMISSION_NOT_ZERO'and not(item?'score')),'missing work has source list not a zero academic result');
reset role;
savepoint attention_source_change;
update app.assessments set assignment_state='CLOSED'where school_id='10000000-0000-4000-8000-000000000001'and id='97010000-0000-4000-8000-000000000003';
set local role cuevo_api;
select ok(not exists(select 1 from jsonb_array_elements(internal.read_attention_signals(100,null,'20000000-0000-4000-8000-000000000030')->'items')item where item->>'type'='missing_due_work'),'closed assignment cannot leak cached missing-work context');
reset role;rollback to attention_source_change;
savepoint attention_new_result;
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','97020000-0000-4000-8000-000000000003','97010000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000024','New source changes current comparison');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.release_marking(internal.mark_submission('97020000-0000-4000-8000-000000000003',9,'New source reviewed',1,0,true),1,true);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000024',true);
select ok(not exists(select 1 from jsonb_array_elements(internal.read_attention_signals(100,null,'20000000-0000-4000-8000-000000000024')->'items')item where item->>'type'='native_result_decline'),'new released source hides the cached comparison before worker refresh');
reset role;rollback to attention_new_result;
insert into app.attention_policies(school_id,version,minimum_decline,max_score,missing_due_count,window_days,approved_by)select'10000000-0000-4000-8000-000000000001',max(version)+1,3,10,2,14,'20000000-0000-4000-8000-000000000001'from app.attention_policies where school_id='10000000-0000-4000-8000-000000000001';
set local role cuevo_api;
select is(jsonb_array_length(internal.read_attention_signals(100,null,'20000000-0000-4000-8000-000000000030')->'items'),0,'policy replacement does not expose outdated cached signal');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select throws_ok('select internal.refresh_native_attention(null,null)','42501',null,'API cannot invoke unscoped source signal refresh');
select throws_ok('select internal.read_attention_signals(101,null,null)','42501',null,'unbounded attention list denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok('select internal.read_attention_signals(25,null,null)','42501',null,'parent cannot read internal attention');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.read_attention_signals(25,null,'20000000-0000-4000-8000-000000000024')$$,'42501',null,'peer cannot request another learner attention');
reset role;
select ok(not has_function_privilege('cuevo_worker','internal.refresh_native_attention(uuid,uuid)','EXECUTE')and not has_function_privilege('authenticated','internal.read_attention_signals(integer,uuid,uuid)','EXECUTE'),'attention uses private purpose-bound source functions only');
select*from finish();rollback;
